46	    private static final RowMapper<RescheduleLink> LINK_MAPPER = (rs, n) -> new RescheduleLink(
47	            rs.getLong("id"),
48	            rs.getLong("predecessor_plan_id"),
49	            rs.getLong("successor_plan_id"),
50	            rs.getLong("created_at"));
51	
52	    private final JdbcTemplate jdbc;
53	
54	    public PlanRepository(JdbcTemplate jdbc) {
55	        this.jdbc = jdbc;
56	    }
57	
58	    /**
59	     * 插入新计划，返回自增主键。
60	     */
61	    public long insertPlan(String scheduleKey, LocalDate opDate, PlanStatus status, long nowMillis) {
62	        KeyHolder keys = new GeneratedKeyHolder();
63	        jdbc.update(con -> {
64	            PreparedStatement ps = con.prepareStatement(
65	                    "INSERT INTO rail_day_plan (schedule_key, op_date, version, status, created_at, updated_at)"
66	                            + " VALUES (?, ?, 1, ?, ?, ?)",
67	                    Statement.RETURN_GENERATED_KEYS);
68	            ps.setString(1, scheduleKey);
69	            ps.setDate(2, Date.valueOf(opDate));
70	            ps.setString(3, status.name());
71	            ps.setLong(4, nowMillis);
72	            ps.setLong(5, nowMillis);
73	            return ps;
74	        }, keys);
75	        return keys.getKey().longValue();
76	    }
77	
78	    /**
79	     * 按业务键查询计划（不加锁）。
80	     */
81	    public Optional<DayPlan> findByKey(String scheduleKey) {
82	        return jdbc.query("SELECT id, schedule_key, op_date, version, status FROM rail_day_plan"
83	                        + " WHERE schedule_key = ?",
84	                PLAN_MAPPER, scheduleKey).stream().findFirst();
85	    }
86	
87	    /**
88	     * 按主键查询计划（不加锁），用于改签链遍历。
89	     */
90	    public Optional<DayPlan> findById(long planId) {
91	        return jdbc.query("SELECT id, schedule_key, op_date, version, status FROM rail_day_plan"
92	                        + " WHERE id = ?",
93	                PLAN_MAPPER, planId).stream().findFirst();
94	    }
95	
96	    /**
97	     * 按业务键查询计划并加行级写锁，须在事务内调用，用于串行化同一计划的更新/发布/取消。
98	     */
99	    public Optional<DayPlan> findByKeyForUpdate(String scheduleKey) {
100	        return jdbc.query("SELECT id, schedule_key, op_date, version, status FROM rail_day_plan"
101	                        + " WHERE schedule_key = ? FOR UPDATE",
102	                PLAN_MAPPER, scheduleKey).stream().findFirst();
103	    }
104	
105	    /**
106	     * 整体替换计划的占用清单：先删后插，保持提交顺序。
107	     */
108	    public void replaceOccupancies(long planId, List<Occupancy> occupancies) {
109	        jdbc.update("DELETE FROM rail_plan_occupancy WHERE plan_id = ?", planId);
110	        insertOccupancies(planId, occupancies);
111	    }
112	
113	    /**
114	     * 批量插入占用。
115	     */
116	    public void insertOccupancies(long planId, List<Occupancy> occupancies) {
117	        jdbc.batchUpdate(
118	                "INSERT INTO rail_plan_occupancy (plan_id, seq, train_no, section_id, start_utc, end_utc)"
119	                        + " VALUES (?, ?, ?, ?, ?, ?)",
120	                occupancies, occupancies.size(),
121	                (ps, o) -> {
122	                    ps.setLong(1, planId);
123	                    ps.setInt(2, o.seq());
124	                    ps.setString(3, o.trainNo());
125	                    ps.setString(4, o.sectionId());
126	                    ps.setLong(5, o.startUtc().toEpochMilli());
127	                    ps.setLong(6, o.endUtc().toEpochMilli());
128	                });
129	    }
130	
131	    /**
132	     * 查询计划占用，按计划内序号升序。
133	     */
134	    public List<Occupancy> findOccupancies(long planId) {
135	        return jdbc.query("SELECT id, plan_id, seq, train_no, section_id, start_utc, end_utc"
136	                        + " FROM rail_plan_occupancy WHERE plan_id = ? ORDER BY seq",
137	                OCCUPANCY_MAPPER, planId);
138	    }
139	
140	    /**
141	     * 更新版本与状态。
142	     */
143	    public void updateVersionAndStatus(long planId, int version, PlanStatus status, long nowMillis) {
144	        jdbc.update("UPDATE rail_day_plan SET version = ?, status = ?, updated_at = ? WHERE id = ?",
145	                version, status.name(), nowMillis, planId);
146	    }
147	
148	    /**
149	     * 仅更新状态（发布/取消不改变版本与占用）。
150	     */
151	    public void updateStatus(long planId, PlanStatus status, long nowMillis) {
152	        jdbc.update("UPDATE rail_day_plan SET status = ?, updated_at = ? WHERE id = ?",
153	                status.name(), nowMillis, planId);
154	    }
155	
156	    /**
157	     * 查询指定运营日、指定区段集合上其他已发布计划的生效时隙（排除给定计划集合）。
158	     */
159	    public List<PublishedSlot> findPublishedSlots(LocalDate opDate, Collection<String> sectionIds,
160	                                                  Collection<Long> excludePlanIds) {
161	        if (sectionIds.isEmpty()) {
162	            return List.of();
163	        }
164	        StringJoiner sectionPlaceholders = new StringJoiner(", ");
165	        sectionIds.forEach(s -> sectionPlaceholders.add("?"));
166	        StringBuilder sql = new StringBuilder(
167	                "SELECT p.schedule_key, o.train_no, o.section_id, o.start_utc, o.end_utc"
168	                        + " FROM rail_plan_occupancy o JOIN rail_day_plan p ON p.id = o.plan_id"
169	                        + " WHERE p.status = 'PUBLISHED' AND p.op_date = ?");
170	        List<Object> args = new ArrayList<>();
171	        args.add(Date.valueOf(opDate));
172	        if (!excludePlanIds.isEmpty()) {
173	            StringJoiner excludePlaceholders = new StringJoiner(", ");
174	            excludePlanIds.forEach(id -> excludePlaceholders.add("?"));
175	            sql.append(" AND p.id NOT IN (").append(excludePlaceholders).append(')');
176	            args.addAll(excludePlanIds);
177	        }
178	        sql.append(" AND o.section_id IN (").append(sectionPlaceholders)
179	                .append(") ORDER BY o.section_id, o.start_utc");
180	        args.addAll(sectionIds);
181	        return jdbc.query(sql.toString(), (rs, n) -> new PublishedSlot(
182	                rs.getString("schedule_key"),
183	                rs.getString("train_no"),
184	                rs.getString("section_id"),
185	                Instant.ofEpochMilli(rs.getLong("start_utc")),
186	                Instant.ofEpochMilli(rs.getLong("end_utc"))), args.toArray());
187	    }
188	
189	    /**
190	     * 追加改签前后继关联（不可变）；唯一约束冲突时抛出 DuplicateKeyException 由上层裁决。
191	     */
192	    public void insertRescheduleLink(long predecessorPlanId, long successorPlanId, long nowMillis) {
193	        jdbc.update("INSERT INTO rail_plan_reschedule_link"
194	                        + " (predecessor_plan_id, successor_plan_id, created_at) VALUES (?, ?, ?)",
195	                predecessorPlanId, successorPlanId, nowMillis);
196	    }
197	
198	    /**
199	     * 查询以指定计划为直接前驱的改签关联（即该计划的直接后继）。
200	     */
201	    public Optional<RescheduleLink> findLinkByPredecessor(long predecessorPlanId) {
202	        return jdbc.query("SELECT id, predecessor_plan_id, successor_plan_id, created_at"
203	                        + " FROM rail_plan_reschedule_link WHERE predecessor_plan_id = ?",
204	                LINK_MAPPER, predecessorPlanId).stream().findFirst();
205	    }
206	
207	    /**
208	     * 查询以指定计划为直接后继的改签关联（即该计划的直接前驱）。
209	     */
210	    public Optional<RescheduleLink> findLinkBySuccessor(long successorPlanId) {
211	        return jdbc.query("SELECT id, predecessor_plan_id, successor_plan_id, created_at"
212	                        + " FROM rail_plan_reschedule_link WHERE successor_plan_id = ?",
213	                LINK_MAPPER, successorPlanId).stream().findFirst();
214	    }
215	
216	    /**
217	     * 获取发布全局互斥锁（单行 FOR UPDATE），串行化所有发布事务。
218	     */
219	    public void acquirePublishLock() {
220	        jdbc.queryForObject("SELECT id FROM publish_lock WHERE id = 1 FOR UPDATE", Integer.class);
221	    }
222	}
