3	import static org.assertj.core.api.Assertions.assertThat;
4	
5	import com.example.starter.plan.service.PlanService;
6	import com.example.starter.plan.web.ApiException;
7	import com.example.starter.plan.web.dto.CreatePlanRequest;
8	import com.example.starter.plan.web.dto.OccupancyRequest;
