429	    private static String key(String prefix) {
430	        return prefix + "-" + UUID.randomUUID();
431	    }
432	
433	    /** 运营日当日 hour 点（Asia/Shanghai）的 UTC 时刻。 */
434	    private static String iso(int hour) {
435	        return iso(hour, 0);
436	    }
437	
438	    /** 运营日加 dayOffset 天后 hour 点（Asia/Shanghai）的 UTC 时刻。 */
439	    private static String iso(int hour, int dayOffset) {
440	        Instant instant = DAY.plusDays(dayOffset).atTime(hour, 0).atZone(SH).toInstant();
441	        return instant.toString();
442	    }
443	
444	    private static String occ(String train, String section, String startIso, String endIso) {
445	        return "{\"trainNo\":\"" + train + "\",\"sectionId\":\"" + section
446	                + "\",\"startUtc\":\"" + startIso + "\",\"endUtc\":\"" + endIso + "\"}";
